}
$bad=Clone $a;$q=$bad.physicalProtection.calls[6];$bad.physicalProtection.calls[6]=$bad.physicalProtection.calls[7];$bad.physicalProtection.calls[7]=$q;Reject {Validate $bad} 'attribute access before provider protection'
$bad=Clone $a;$bad.physicalProtection.calls=@($bad.physicalProtection.calls)+@($bad.physicalProtection.calls[0]);Reject {Validate $bad} 'extra native operation'
