foreach($name in @('Invoke-LabNativeReconstruct.ps1','Invoke-LabConvertedVerification.ps1')){$text=Get-Content -LiteralPath (Join-Path $repo ('scripts\'+$name)) -Raw;foreach($required in @('Convert-RetainedProtectionHex','Get-RetainedProtectionGuid','Assert-RetainedProtectionLayout','Assert-RetainedProbeProtection','NativeShadowReadOnlyAttachment.cs','NativeMountBoundary.cs')){Check ($text.Contains($required)) ('shared protection dependency '+$name+'/'+$required)}}
