$runId=$diag.runId;$observation='f'*32;$request=[pscustomobject]@{target=$targetBinding};$prepared=[pscustomobject]@{shadowEvidenceSha256=$diag.sourcePreparationSha256};$shadow=[pscustomobject]@{shadow=$expected;finalVhd=$diag.finalVhd};$nativeSource=[pscustomobject]@{sha256=('c'*64)};$attachmentSource=[pscustomobject]@{sha256=('d'*64)};$protectionNativeSource=[pscustomobject]@{sha256=$protectionHash};$mountNativeSource=[pscustomobject]@{sha256=$mountHash}
